_LBASE = 0x1100
_VBASE = 0x1161
_TBASE = 0x11A7
_VCOUNT = 21
_TCOUNT = 28
_NCOUNT = _VCOUNT * _TCOUNT
_SCOUNT = 19 * _NCOUNT

_names = None
_lookup_table = None


def _load_names():
    global _names
    if _names is None:
        deltas = _varints(_blob(_D_NAME_CPS))
        cps = []
        cp = -1
        for d in deltas:
            cp = cp + d
            cps.append(cp)
        names = []
        prev = ""
        for line in _blob(_D_NAMES).decode("ascii").split("\n"):
            prev = prev[:ord(line[0]) - 48] + line[1:]
            names.append(prev)
        _names = (cps, names)
    return _names


def _hex(cp):
    h = "%X" % cp
    while len(h) < 4:
        h = "0" + h
    return h


def _name(cp):
    if _SBASE <= cp < _SBASE + _SCOUNT:
        s = cp - _SBASE
        return ("HANGUL SYLLABLE " + _JAMO_L[s // _NCOUNT] +
                _JAMO_V[(s % _NCOUNT) // _TCOUNT] + _JAMO_T[s % _TCOUNT])
    for r in _NAME_RANGES:
        if r[1] <= cp <= r[2]:
            return r[0] + _hex(cp)
    cps, names = _load_names()
    i = _bisect_right(cps, cp) - 1
    if i < 0 or cps[i] != cp:
        return None
    return names[i]


def name(chr, *default):
    n = _name(_cp(chr, "name"))
    if n is None:
        if default:
            return default[0]
        raise ValueError("no such name")
    return n


def _load_lookup():
    global _lookup_table
    if _lookup_table is None:
        cps, names = _load_names()
        t = {}
        i = 0
        while i < len(cps):
            t[names[i]] = cps[i]
            i = i + 1
        _lookup_table = t
    return _lookup_table


def _parse_hex(s):
    if len(s) < 4 or len(s) > 6:
        return -1
    v = 0
    for c in s:
        if "0" <= c <= "9":
            v = v * 16 + (ord(c) - 48)
        elif "A" <= c <= "F":
            v = v * 16 + (ord(c) - 55)
        else:
            return -1
    return v


def lookup(name):
    if isinstance(name, (bytes, bytearray)):
        name = name.decode("ascii")
    key = name.upper()
    if key.startswith("HANGUL SYLLABLE "):
        rest = key[16:]
        s = 0
        while s < _SCOUNT:
            if _name(_SBASE + s)[16:] == rest:
                return chr(_SBASE + s)
            s = s + 1
    for r in _NAME_RANGES:
        if key.startswith(r[0]):
            v = _parse_hex(key[len(r[0]):])
            if r[1] <= v <= r[2] and key == r[0] + _hex(v):
                return chr(v)
    cp = _load_lookup().get(key)
    if cp is None:
        raise KeyError("undefined character name '" + name + "'")
    return chr(cp)


# ------------------------------------------------- decomposition, numbers

_decomp = None
_numeric = None


def _load_decomp():
    global _decomp
    if _decomp is None:
        t = {}
        cp = 0
        for line in _blob(_D_DECOMP).decode("ascii").split("\n"):
            sp = line.index(" ")
            cp = cp + int(line[:sp], 16)
            t[cp] = line[sp + 1:]
        _decomp = t
    return _decomp


def decomposition(chr):
    cp = _cp(chr, "decomposition")
    if _SBASE <= cp < _SBASE + _SCOUNT:
        s = cp - _SBASE
        d = _hex(_LBASE + s // _NCOUNT) + " " + _hex(_VBASE + (s % _NCOUNT) // _TCOUNT)
        if s % _TCOUNT:
            d = d + " " + _hex(_TBASE + s % _TCOUNT)
        return d
    return _load_decomp().get(cp, "")


def _load_numeric():
    global _numeric
    if _numeric is None:
        t = {}
        cp = 0
        for line in _blob(_D_NUMERIC).decode("ascii").split("\n"):
            f = line.split(":")
            cp = cp + int(f[0], 16)
            dec = None
            dig = None
